import XCTest
@testable import PhotoCraftCore

final class PatternPixelFillTests:XCTestCase{
  func pattern(_ depth:PixelDepth = .u8)throws->RasterPattern{var surface=try Surface(width:2,height:2,depth:depth);surface.setPixel(x:0,y:0,Pixel(1,0,0));surface.setPixel(x:1,y:0,Pixel(0,1,0));surface.setPixel(x:0,y:1,Pixel(0,0,1));surface.setPixel(x:1,y:1,Pixel(1,1,1,0));return try RasterPattern(name:"Owned checker",surface:surface,id:"owned-checker")}
  func fixture(_ depth:PixelDepth = .u8)throws->CraftDocument{var d=try CraftDocument(width:12,height:10,depth:depth);d.layers[0].content = .raster(try Surface(width:12,height:10,depth:depth));return d}
  func testSavedPatternTilingAllDepthsAndTransparentTexelsKeepOriginalWords()throws{
    for depth in PixelDepth.allCases{var d=try fixture(depth);guard case .raster(var input)=d.layers[0].content else{return XCTFail()};input.setPixel(x:1,y:1,Pixel(0.25,0.5,0.75,0.25));d.layers[0].content = .raster(input);let before=d,asset=try pattern(depth);var settings=PixelPaintSettings(color:.clear);try Command.pixelPaint(.init(.fill,target:.layer(d.layers[0].id),settings:settings,pattern:asset)).apply(to:&d);guard case .raster(let out)=d.layers[0].content else{return XCTFail()};for y in 0..<10{for x in 0..<12{if x%2==1 && y%2==1{XCTAssertTrue(out.pixel(x:x,y:y).hasSameBits(as:input.pixel(x:x,y:y)))}else{XCTAssertEqual(out.pixel(x:x,y:y),asset.surface.pixel(x:x%2,y:y%2))}}};XCTAssertEqual(d.minimumArchiveVersion,before.minimumArchiveVersion);XCTAssertNil(d.patterns);settings.opacity=0;var unchanged=before;try Command.pixelPaint(.init(.fill,target:.layer(unchanged.layers[0].id),settings:settings,pattern:asset)).apply(to:&unchanged);XCTAssertEqual(unchanged,before)}
  }
  func testPatternPaintModesMasksAndInvertedScalarTargetsRetainOtherPlanes()throws{
    for depth in PixelDepth.allCases{var d=try fixture(depth);d.selection = .init(x:2,y:2,width:8,height:6);d.layers[0].mask=try Surface(width:12,height:10,depth:depth,fill:.white);let color=d.layers[0].content,asset=try pattern(depth);var settings=PixelPaintSettings(color:.black);settings.opacity=0.5;settings.mode = .multiply;try Command.pixelPaint(.init(.fill,target:.mask(d.layers[0].id),settings:settings,pattern:asset)).apply(to:&d);XCTAssertEqual(d.layers[0].content,color);XCTAssertEqual(d.layers[0].mask?.pixel(x:3,y:3),.white);var options=ChannelDisplayOptions();options.indicates = .selectedAreas;let channel=AlphaChannel(name:"Inverse",pixels:try Surface(width:12,height:10,depth:depth,fill:Pixel(0.2,0.2,0.2)),options:options);d.alphaChannels=[channel];let before=d;try Command.pixelPaint(.init(.fill,target:.channel(.alpha(channel.id)),settings:settings,pattern:asset)).apply(to:&d);XCTAssertEqual(d.layers,before.layers);XCTAssertTrue(try XCTUnwrap(d.alphaChannels?.first).pixels.pixel(x:3,y:3).hasSameBits(as:channel.pixels.pixel(x:3,y:3)));XCTAssertNotEqual(d.alphaChannels?.first?.pixels.pixel(x:2,y:2),channel.pixels.pixel(x:2,y:2))}
  }
  func testDocumentAnchoringIntegerPhaseAndStorageGrowthKeepOffCanvasPixelsAndMasks()throws{
    var d=try fixture(),pixels=try Surface(width:4,height:4);pixels.setPixel(x:0,y:0,Pixel(0.2,0.3,0.4));d.layers[0].content = .raster(pixels);d.layers[0].x = -2;d.layers[0].y = -1;d.layers[0].mask=try Surface(width:4,height:4,fill:.white);var properties=MaskProperties();properties.linked=false;d.layers[0].maskProperties=properties;d.selection = .init(x:4,y:4,width:4,height:4);let old=d.layers[0],asset=try pattern();var placement=PatternPlacement();placement.phaseX=1;placement.phaseY = -1;try Command.pixelPaint(.init(.fill,target:.layer(old.id),settings:.init(color:.white),pattern:asset,placement:placement)).apply(to:&d);XCTAssertEqual(d.layers[0].mask,old.mask);XCTAssertEqual(d.layers[0].maskCoordinateTransform,old.maskCoordinateTransform);guard case .raster(let out)=d.layers[0].content else{return XCTFail()};XCTAssertEqual(out.pixel(x:0,y:0),pixels.pixel(x:0,y:0));let point=try d.layers[0].coordinateTransform.inverted().point(4.5,5.5);XCTAssertEqual(out.pixel(x:Int(point.x),y:Int(point.y)),asset.surface.pixel(x:1,y:0))
  }
  func testSelfContainedPortableActionArchiveHistoryAndInvalidRequestsStayAtomic()async throws{
    let source=try fixture(),asset=try pattern();var session=EditorSession(document:source);try session.startActionRecording(name:"Pattern");try session.execute(.pixelPaint(.init(.fill,target:.layer(source.layers[0].id),settings:.init(),pattern:asset)));let result=session.document;var replay=source;try XCTUnwrap(session.actionRecording?.snapshot).apply(to:&replay);XCTAssertEqual(replay,result);XCTAssertEqual(try NativeArchive.decode(NativeArchive.encodeChunked(result)),result);try session.undo();XCTAssertEqual(session.document,source);try session.redo();XCTAssertEqual(session.document,result)
    var placement=PatternPlacement();placement.scale=0;var bad=asset;bad.name="";for request in [PixelPaintRequest(.stroke,target:.layer(source.layers[0].id),settings:.init(),pattern:asset),.init(.fill,target:.layer(source.layers[0].id),settings:.init(),placement:.init()),.init(.fill,target:.layer(source.layers[0].id),settings:.init(),pattern:bad),.init(.fill,target:.layer(source.layers[0].id),settings:.init(),pattern:asset,placement:placement)]{var d=source;XCTAssertThrowsError(try Command.pixelPaint(request).apply(to:&d));XCTAssertEqual(d,source)}
    let task=Task{while !Task.isCancelled{await Task.yield()};var d=source;try Command.pixelPaint(.init(.fill,target:.layer(source.layers[0].id),settings:.init(),pattern:asset)).apply(to:&d)};task.cancel();do{try await task.value;XCTFail()}catch{XCTAssertTrue(error is CancellationError)}
  }
  func testSparseMaximumCanvasLocalizedPatternAndUniformImplicitPatternDoNotMaterializePlane()throws{
    var d=try CraftDocument(width:300000,height:300000);d.layers[0].content = .raster(try Surface(width:300000,height:300000));d.selection = .init(x:10000,y:12000,width:4,height:4);try Command.pixelPaint(.init(.fill,target:.layer(d.layers[0].id),settings:.init(),pattern:pattern())).apply(to:&d);guard case .raster(let out)=d.layers[0].content else{return XCTFail()};XCTAssertEqual(out.pixel(x:10000,y:12000),Pixel(1,0,0));XCTAssertEqual(out.pixel(x:2,y:2),.clear);XCTAssertLessThan(out.allocatedBytes,2_097_152);d.selection=nil;let uniform=try RasterPattern(name:"Solid",surface:Surface(width:1,height:1,fill:.black),id:"solid");try Command.pixelPaint(.init(.fill,target:.layer(d.layers[0].id),settings:.init(),pattern:uniform)).apply(to:&d);guard case .raster(let filled)=d.layers[0].content else{return XCTFail()};XCTAssertEqual(filled.pixel(x:299999,y:299999),.black);XCTAssertLessThan(filled.allocatedBytes,2_097_152)
  }
  func testOwnedPatternFillOutputsCapturedForIndependentRGBAReader()throws{
    var rows:[[String:Any]]=[];for selected in [false,true]{for shifted in [false,true]{for opacity:Float in [1,0.5]{var d=try fixture();if selected{d.selection = .init(x:2,y:2,width:8,height:6)};var placement=PatternPlacement();if shifted{placement.phaseX=1;placement.phaseY = -1};var settings=PixelPaintSettings(color:.clear);settings.opacity=opacity;try Command.pixelPaint(.init(.fill,target:.layer(d.layers[0].id),settings:settings,pattern:pattern(),placement:placement)).apply(to:&d);guard case .raster(let out)=d.layers[0].content else{return XCTFail()};var rgba:[Int]=[];for y in 0..<10{for x in 0..<12{let p=out.pixel(x:x,y:y);rgba += [p.r,p.g,p.b,p.a].map{Int((unit($0)*255).rounded())}}};rows.append(["selected":selected,"phaseX":placement.phaseX,"phaseY":placement.phaseY,"opacity":opacity,"rgba":rgba])}}};if let path=ProcessInfo.processInfo.environment["PHOTATO_TEST_CAPTURE_DIR"]{let dir=URL(fileURLWithPath:path);try FileManager.default.createDirectory(at:dir,withIntermediateDirectories:true);try JSONSerialization.data(withJSONObject:["width":12,"height":10,"rows":rows],options:.sortedKeys).write(to:dir.appendingPathComponent("pattern-pixel-fill-analytical.json"))}
  }
}
